 [('A spill ___ have entered the water. (could)','could','possibilidade.',None),('The factory ___ have reported it. (should)','should','crítica.',None),('Heat may have ___ oxygen. (reduce, part.)','reduced','particípio.',None),('We ___ have known earlier. (can’t)','can’t','impossível.',None)],
